CREATE TABLE teachers (
  id    BIGSERIAL PRIMARY KEY,
  name  TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE
);

CREATE TABLE courses (
  id         BIGSERIAL PRIMARY KEY,
  title      TEXT NOT NULL,
  teacher_id BIGINT NOT NULL REFERENCES teachers(id) ON DELETE RESTRICT
);

CREATE TABLE students (
  id    BIGSERIAL PRIMARY KEY,
  email TEXT NOT NULL UNIQUE
);

-- many-to-many: one row per (student, course) pair
CREATE TABLE enrollments (
  student_id  BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  course_id   BIGINT NOT NULL REFERENCES courses(id)  ON DELETE CASCADE,
  enrolled_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (student_id, course_id)   -- no duplicate enrollments
);

-- Primary keys and UNIQUE constraints get an index automatically.
-- Foreign key columns do NOT in PostgreSQL: index them yourself.
CREATE INDEX idx_orders_customer ON orders (customer_id);

-- Composite: equality column first, range or sort column last.
-- It also serves queries on customer_id alone, which makes the
-- single-column index above redundant once this one exists.
CREATE INDEX idx_orders_customer_created ON orders (customer_id, created_at);

-- Filter and sort both come straight from the composite index:
SELECT id, total_cents, created_at
FROM orders
WHERE customer_id = 42
ORDER BY created_at DESC
LIMIT 20;

-- Expression index for case-insensitive lookups
CREATE INDEX idx_users_email_lower ON users (LOWER(email));
SELECT id FROM users WHERE LOWER(email) = LOWER('Dana@Example.com');

